//! Concealed marker check: clipboard content written by a password manager is
//! neither broadcast nor recorded in history.
//!
//! Each platform recognizes the de facto standard clipboard marker:
//! - macOS: pasteboard types contain `org.nspasteboard.ConcealedType`
//!   (1Password, Keychain and others all set it)
//! - Windows: clipboard formats contain
//!   `ExcludeClipboardContentFromMonitorProcessing` (the cloud clipboard
//!   convention) or the older `Clipboard Viewer Ignore` (still used across the
//!   KeePass ecosystem)
//! - Linux: no uniform standard, and querying MIME targets needs X11/Wayland
//!   bindings, so v1 always reports not concealed; support for
//!   `x-kde-passwordManagerHint` (KeePassXC) is deferred to v1.x
//!
//! The check and the subsequent content read are not atomic (milliseconds
//! apart), so an extreme race can miss one round; polling clipboard tools
//! (Maccy and friends) work the same way, which is acceptable.

/// Whether the current clipboard content carries a concealed marker; on a hit
/// the watcher skips the round entirely and does not read the content
#[cfg(target_os = "macos")]
pub fn is_concealed() -> bool {
    // autoreleasepool: types() returns an autoreleased object and the caller
    // is a long-lived tokio worker thread (no implicit pool), so wrapping
    // keeps objects from accumulating on a pool-less thread
    objc2::rc::autoreleasepool(|_| {
        // Safe binding generated by objc2: NSPasteboard is accessible from any
        // thread (same as stamp.rs)
        let pasteboard = objc2_app_kit::NSPasteboard::generalPasteboard();
        // None types (a guard for the nullable case; an empty clipboard is
        // really Some(empty array)) counts as not concealed
        let Some(types) = pasteboard.types() else {
            return false;
        };
        types
            .iter()
            .any(|t| t.to_string() == "org.nspasteboard.ConcealedType")
    })
}

/// Whether the current clipboard content carries a concealed marker; on a hit
/// the watcher skips the round entirely and does not read the content
#[cfg(windows)]
#[expect(
    unsafe_code,
    reason = "RegisterClipboardFormatW/IsClipboardFormatAvailable 为纯查询系统调用, 无需 OpenClipboard, 无指针与内存安全影响"
)]
pub fn is_concealed() -> bool {
    use windows_sys::Win32::System::DataExchange::{
        IsClipboardFormatAvailable, RegisterClipboardFormatW,
    };
    // Check both generations of the de facto standard: tools that only set
    // the older marker (older KeePass versions and friends) must be exempt too
    let markers = [
        windows_sys::core::w!("ExcludeClipboardContentFromMonitorProcessing"),
        windows_sys::core::w!("Clipboard Viewer Ignore"),
    ];
    markers.into_iter().any(|name| {
        // Registering the same format name again always returns the same ID
        // (an atom table lookup, negligible cost); a 0 return means
        // registration failed (atom table exhausted, very rare) and counts as
        // no marker
        let id = unsafe { RegisterClipboardFormatW(name) };
        id != 0 && unsafe { IsClipboardFormatAvailable(id) != 0 }
    })
}

/// Whether the current clipboard content carries a concealed marker; on a hit
/// the watcher skips the round entirely and does not read the content
#[cfg(not(any(target_os = "macos", windows)))]
pub fn is_concealed() -> bool {
    false
}
